@st.cache_data
def load_lookup_tables():
    airline = pd.read_csv("lookup/AIRLINE_LOOKUP.csv")
    airport = pd.read_csv("lookup/AIRPORT_LOOKUP.csv")
    route = pd.read_csv("lookup/ROUTE_LOOKUP.csv")
    return airline, airport, route


airline_lookup, airport_lookup, route_lookup = load_lookup_tables()

# ==========================================================
# RISK TIER LOGIC
# ==========================================================

def get_risk_tier(delay_probability: float):
    if delay_probability < 15:
        return {"tier": "low", "badge_class": "risk-low", "result_class": "result-low",
                "label": "Low Risk", "headline": "Will Be On-Time", "icon": "🟢"}
    elif delay_probability < 25:
        return {"tier": "medium", "badge_class": "risk-medium", "result_class": "result-medium",
                "label": "Medium Risk", "headline": "Could Be Delayed", "icon": "🟡"}
    else:
        return {"tier": "high", "badge_class": "risk-high", "result_class": "result-high",
                "label": "High Risk", "headline": "Will Be Delayed", "icon": "🔴"}

# ==========================================================
# TOP AIRLINES FOR ROUTE
# ==========================================================

def get_top_airlines_for_route(route_lookup, airline_lookup, origin_code, destination_code, top_n=3, exclude_code=None):
    """
    Return the best available historical airline recommendations.

    If ROUTE_LOOKUP contains AirlineCode + airline performance columns, use
    route-specific history. Otherwise use the historical airline metrics in
    AIRLINE_LOOKUP (lowest monthly delay rate, then highest reliability).
    """
    matches = route_lookup[
        (route_lookup["Origin"] == origin_code) &
        (route_lookup["Dest"] == destination_code)
    ].copy()

    if "AirlineCode" in matches.columns and not matches.empty:
        rank_col = None
        for candidate in ["OnTimeRate", "OnTimePct", "Rating", "AvgDelay", "DelayRate"]:
            if candidate in matches.columns:
                rank_col = candidate
                break

        if rank_col:
            matches[rank_col] = pd.to_numeric(matches[rank_col], errors="coerce")
            ascending = rank_col in ["AvgDelay", "DelayRate"]
            matches = matches.sort_values(rank_col, ascending=ascending, na_position="last")

        codes = matches.drop_duplicates(subset="AirlineCode")["AirlineCode"].tolist()
    else:
        # The supplied ROUTE_LOOKUP has no AirlineCode, so recommendations
        # cannot be route-specific. Use historical airline-level performance.
        ranked = airline_lookup.copy()
        if "AirlineMonthlyDelayRate" in ranked.columns:
            ranked["AirlineMonthlyDelayRate"] = pd.to_numeric(
                ranked["AirlineMonthlyDelayRate"], errors="coerce"
            )
        if "AirlineReliabilityScore" in ranked.columns:
            ranked["AirlineReliabilityScore"] = pd.to_numeric(
                ranked["AirlineReliabilityScore"], errors="coerce"
            )
        ranked = ranked[
            ranked["AirlineCode"].notna() &
            ranked["AirlineLabel"].notna()
        ]
        ranked = ranked[
            ranked["AirlineMonthlyDelayRate"].notna()
        ].sort_values(
            ["AirlineMonthlyDelayRate", "AirlineReliabilityScore"],
            ascending=[True, False],
            na_position="last"
        )
        codes = ranked["AirlineCode"].tolist()

    if exclude_code:
        codes = [c for c in codes if c != exclude_code]

    results = []
    for code in codes:
        name_row = airline_lookup.loc[
            airline_lookup["AirlineCode"] == code, "AirlineLabel"
        ]
        if not name_row.empty:
            results.append(name_row.iloc[0])
        if len(results) == top_n:
            break

    return results

